import{_ as o,c as r,o as t,aj as n}from"./chunks/framework.DaB7tcLF.js";const c=JSON.parse('{"title":"World of Open Source Survey","description":"","frontmatter":{"title":"World of Open Source Survey","date":"2026-10-16","banner":"assets/blog/20261016_neonephos_world_of_open_source_survey_banner.svg","authors":["neonephos-team"],"tags":["2026","news"],"published":true},"headers":[],"relativePath":"20261016_world_of_open_source_survey.md","filePath":"20261016_world_of_open_source_survey.md"}'),a={name:"20261016_world_of_open_source_survey.md"};function s(i,e,l,h,p,u){return t(),r("div",null,e[0]||(e[0]=[n('<h1 id="world-of-open-source-europe-spotlight" tabindex="-1">World of Open Source Europe: Spotlight <a class="header-anchor" href="#world-of-open-source-europe-spotlight" aria-label="Permalink to &quot;World of Open Source Europe: Spotlight&quot;">​</a></h1><p>On October 7th during the Open Source Summit in Prague, the Linux Foundation released the results of the fifth annual <a href="https://www.linuxfoundation.org/research/world-of-open-source-eu-2026?hsLang=en" target="_blank" rel="noreferrer">State of Open Source in Europe survey</a>. For this year&#39;s edition, which the NeoNephos Foundation co-sponsored, the report grants the topic of digital sovereignty special attention.</p><h2 id="why-digital-sovereignty-matters" tabindex="-1">Why digital Sovereignty matters <a class="header-anchor" href="#why-digital-sovereignty-matters" aria-label="Permalink to &quot;Why digital Sovereignty matters&quot;">​</a></h2><p>The numbers could not be more stark: 94% of European respondents (n=264) rate <em>digital sovereignty</em> at least <em>somewhat important</em> to their organization, 61.5% even <em>very important</em> (<a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">Q18</a>). According to the survey, the main drivers behind this sentiment are <em>Security and privacy</em> (71%), <em>Vendor lock-in and cost risk</em> (55%) and <em>National or regional interests</em> (47%) (<a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">Q19</a>). An important takeaway is that this sentiment is shared across the world, as the data highlights similar results for respondents <em>outside</em> Europe. Anecdotically, we can attest to that as our visits to <a href="https://neonephos.org/events/2026_06_18_KubeCon_India" target="_blank" rel="noreferrer">KubeCon + CloudNativeCon India</a> and <a href="https://github.com/neonephos/events/issues/11" target="_blank" rel="noreferrer">KubeCon + CloudNativeCon Japan</a> showed great interest in our foundation from local companies and attendants.</p><p>Open source can help advance digital sovereignty efforts which extends far beyond code. The survey suggests that exploitation depth is linked to the maturity level of the internal open source processes: Respondents (n=87) whose organizations reportedly have advanced open source governance processes report a higher return of benefits (4.6x) as opposed to respondents whose organizations have no formal governance at all (3.6x).</p><h2 id="the-case-of-foundation-led-open-source" tabindex="-1">The case of foundation led open source <a class="header-anchor" href="#the-case-of-foundation-led-open-source" aria-label="Permalink to &quot;The case of foundation led open source&quot;">​</a></h2><p>In light of an uncertain environment, trust is an important component in evaluating open source components: 38% of all respondents who have answered <em>Which open source governance model makes your organization most likely to adopt a project?</em> (n=197) put neutral foundation-hosted projects at the top of the list - topping all other answers. This underscores the relevance of the NeoNephos Foundation as governing framework for enterprise ready open source components: Trust is earned through neutral governance, community input and a proven path for project longevity and maintenance. By participating in NNF in any shape - membership, contributions and more - an organization maximizes exploitation potential not just in relation to a singular project but gains access to an entire ecosystem.</p><p>For more insights, read the entire survey <a href="https://www.linuxfoundation.org/hubfs/Research%20Reports/WorldofOS_EUSpotlight_2026_final.pdf?hsLang=en" target="_blank" rel="noreferrer">here</a>. We are thankful for all contributors and hope to see you aboard next year as well!</p><h3 id="further-links" tabindex="-1">Further Links <a class="header-anchor" href="#further-links" aria-label="Permalink to &quot;Further Links&quot;">​</a></h3><ul><li><a href="https://www.linuxfoundation.org/hubfs/Research%20Reports/WorldofOS_EUSpotlight_2026_final.pdf?hsLang=en" target="_blank" rel="noreferrer">The World of Open Source Survey Report</a></li><li><a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">The World of Open Source Survey Dataset</a></li><li><a href="https://docs.google.com/presentation/d/1RyUbfwHopJ0iYS7jUoRMST79JwXfWGvhiHquosWt9k8/edit?usp=sharing" target="_blank" rel="noreferrer">The World of Open Source Survey Summary</a></li></ul>',10)]))}const f=o(a,[["render",s]]);export{c as __pageData,f as default};
